      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value / 10u));
      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value % 10u));
    } else if (value >= 10u) {
      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value / 10u));
      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value % 10u));
    } else {
      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value));
    }
    buffer[index++] = static_cast<OutChar>(delimiter);
    return index;
  }

template <typename OutChar>
  size_t build_terminal_color_escape(OutChar* buffer, unsigned value,
                                     bool is_background) const {
    if (is_background) value += 10u;
    size_t index = write_esc_csi_prefix_to(buffer);
    if (value >= 100u) {
      buffer[index++] = static_cast<OutChar>('1');
      value %= 100u;
    }
    buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value / 10u));
    buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + value % 10u));
    buffer[index++] = static_cast<OutChar>('m');
    buffer[index++] = static_cast<OutChar>('\0');
    return index;
  }

template <typename OutChar>
  size_t build_rgb_color_escape(OutChar* buffer, uint32_t rgb_color,
                                bool is_background) const {
    const char* prefix = is_background ? "\x1b[48;2;" : "\x1b[38;2;";
    for (int i = 0; i < 7; ++i)
      buffer[i] = static_cast<OutChar>(prefix[i]);
    uint8_t r = static_cast<uint8_t>((rgb_color >> 16) & 0xffu);
    uint8_t g = static_cast<uint8_t>((rgb_color >> 8) & 0xffu);
    uint8_t b = static_cast<uint8_t>(rgb_color & 0xffu);
    size_t index = 7;
    index += write_uint_to_esc(buffer + index, r, ';');
    index += write_uint_to_esc(buffer + index, g, ';');
    index += write_uint_to_esc(buffer + index, b, 'm');
    buffer[index++] = static_cast<OutChar>('\0');
    return index;
  }

uint8_t emphasis_code_for_bit(uint8_t emphasis, uint8_t mask, uint8_t code) const {
    if ((emphasis & mask) == 0) return 0;
    return code;
  }

template <typename OutChar>
  size_t build_emphasis_escape(OutChar* buffer) const {
    uint8_t codes[8];
    codes[0] = emphasis_code_for_bit(style_emphasis_, 1u, 1u);
    codes[1] = emphasis_code_for_bit(style_emphasis_, 2u, 2u);
    codes[2] = emphasis_code_for_bit(style_emphasis_, 4u, 3u);
    codes[3] = emphasis_code_for_bit(style_emphasis_, 8u, 4u);
    codes[4] = emphasis_code_for_bit(style_emphasis_, 16u, 5u);
    codes[5] = emphasis_code_for_bit(style_emphasis_, 32u, 7u);
    codes[6] = emphasis_code_for_bit(style_emphasis_, 64u, 8u);
    codes[7] = emphasis_code_for_bit(style_emphasis_, 128u, 9u);
    size_t index = 0;
    for (size_t i = 0; i < 8; ++i) {
      if (codes[i] == 0) continue;
      index += write_esc_csi_prefix_to(buffer + index);
      buffer[index++] = static_cast<OutChar>(static_cast<char>('0' + codes[i]));
      buffer[index++] = static_cast<OutChar>('m');
    }
    buffer[index++] = static_cast<OutChar>('\0');
    return index;
  }

template <typename Buffer>
  bool append_bound_style_codes(Buffer& buf) {
    bool has_style = false;
    Char scratch[40];
    if (style_has_emphasis()) {
      has_style = true;
      build_emphasis_escape(scratch);
      size_t count = 0;
      while (scratch[count] != static_cast<Char>('\0')) ++count;
      append_chars_to_buffer(buf, scratch, count);
    }
    if (style_has_foreground()) {
      has_style = true;
      if (style_foreground_is_rgb())
        build_rgb_color_escape(scratch, style_foreground_, false);
      else
        build_terminal_color_escape(scratch, static_cast<unsigned>(style_foreground_),
                                    false);
      size_t count = 0;
      while (scratch[count] != static_cast<Char>('\0')) ++count;
      append_chars_to_buffer(buf, scratch, count);
    }
    if (style_has_background()) {
      has_style = true;
      if (style_background_is_rgb())
        build_rgb_color_escape(scratch, style_background_, true);
      else
        build_terminal_color_escape(scratch, static_cast<unsigned>(style_background_),
                                    true);
      size_t count = 0;
      while (scratch[count] != static_cast<Char>('\0')) ++count;
      append_chars_to_buffer(buf, scratch, count);
    }
    return has_style;
  }

template <typename Buffer>
  bool append_style_codes(Buffer& buf, bool has_emphasis, uint8_t emphasis,
                          bool has_foreground, bool foreground_is_rgb,
                          uint32_t foreground, bool has_background,
                          bool background_is_rgb, uint32_t background) {
    bind_text_style(has_emphasis, emphasis, has_foreground, foreground_is_rgb,
                    foreground, has_background, background_is_rgb, background);
    return append_bound_style_codes(buf);
  }

template <typename Buffer>
  void maybe_reset_style(Buffer& buf, bool has_style) {
    if (!has_style) return;
    append_reset_sequence(buf);
  }

void bind_duration_specs(int precision, int width) {
    duration_precision_ = precision;
    duration_width_ = width;
  }

template <typename OutputIt, typename Rep>
  OutputIt write_integral_duration(OutputIt out, Rep value) {
    bind_duration_specs(-1, 0);
    return detail::write<Char>(out, value);
  }

template <typename OutputIt, typename Rep>
  OutputIt write_floating_duration(OutputIt out, Rep value, int precision) {
    bind_duration_specs(precision, 0);
    auto specs = basic_format_specs<Char>();
    specs.precision = precision;
    if (precision > 0)
      specs.type = static_cast<char>('f');
    else
      specs.type = static_cast<char>('g');
    return detail::write<Char>(out, value, specs);
  }

template <typename OutputIt>
  OutputIt copy_ascii_unit(OutputIt out, const char* unit) {
    if (!unit) return out;
    for (const char* p = unit; *p; ++p) {
      unsigned value = static_cast<unsigned>(static_cast<unsigned char>(*p));
      if (value < 0x80u) {
        *out++ = static_cast<Char>(*p);
        continue;
      }
      if (sizeof(Char) == 1) {
        *out++ = static_cast<Char>(*p);
        continue;
      }
      *out++ = static_cast<Char>(value);
    }
    return out;
  }

template <typename OutputIt>
  OutputIt write_named_duration_unit(OutputIt out, const char* unit) {
    if (!unit) {
      *out++ = static_cast<Char>('s');
      return out;
    }
    bool ascii_only = true;
    for (const char* p = unit; *p; ++p) {
      if (static_cast<unsigned char>(*p) >= 0x80u) {
        ascii_only = false;
        break;
      }
    }
    if (ascii_only) return write_unit_by_name(out, unit);
    if (!uses_wide_encoding()) return copy_ascii_unit(out, unit);
    string_view unit_view(unit);
    detail::utf8_to_utf16 converted(unit_view);
    const wchar_t* begin = converted.c_str();
    size_t count = converted.size();
    for (size_t i = 0; i < count; ++i)
      *out++ = static_cast<Char>(begin[i]);
    return out;
  }

template <typename Period, typename OutputIt>
  OutputIt write_ratio_duration_unit(OutputIt out) {
    *out++ = static_cast<Char>('[');
    out = detail::write<Char>(out, Period::num);
    if (detail::const_check(Period::den != 1)) {
      *out++ = static_cast<Char>('/');
      out = detail::write<Char>(out, Period::den);
    }
    *out++ = static_cast<Char>(']');
    *out++ = static_cast<Char>('s');
    return out;
  }

void bind_file_chunk_limit(size_t limit) {
    if (limit == 0)
      file_chunk_limit_ = static_cast<size_t>(detail::max_value<std::streamsize>());
    else
      file_chunk_limit_ = limit;
  }

size_t next_stream_chunk_size(size_t remaining) const {
    if (remaining <= file_chunk_limit_) return remaining;
    return file_chunk_limit_;
  }

template <typename Stream, typename C>
  void write_stream_buffer(Stream& os, const C* data, size_t size) {
    bind_file_chunk_limit(static_cast<size_t>(detail::max_value<std::streamsize>()));
    const C* cursor = data;
    size_t remaining = size;
    while (remaining != 0) {
      size_t chunk = next_stream_chunk_size(remaining);
      os.write(cursor, static_cast<std::streamsize>(chunk));
      cursor += chunk;
      remaining -= chunk;
    }
  }

bool should_flush_file_buffer(size_t size, size_t capacity) {
    bind_file_chunk_limit(capacity);
    if (capacity == 0) return false;
    return size == capacity;
  }

bool has_buffered_file_data(size_t size) const { return size != 0; }

